-- sha256: 276d85ec69b2f6ec1beb0db9c12044b57ecf73287ab00db35008b7d9491b3f58
create temporary view user_item_${grass_region_without_quote} as
select
    grass_date as local_date
    ,user_id
    ,order_item_id as item_id
    ,'Video' as scenario
    ,order_id
    ,case when is_ads = true then 'true' else 'false' end as is_ads
    ,video_order_fraction as order_cnt
    ,gmv_usd as gmv
from
    mp_content_oa.dwd_video_order_omni_local_content_direct_final_detail_di
where
    grass_region in (${grass_region})
    and grass_date between date_add(date(${local_date}), -14) and date(${local_date})
    and tz_type = 'local'
    and get_json_object(click_video_property, '$.business_id') in ('1003', '1019')

union all

select
    grass_date as local_date
    ,order_buyer_id as user_id
    ,order_item_id as item_id
    ,'Live' as scenario
    ,order_id
    ,is_ads -- string: true / false
    ,ls_order_fraction as order_cnt
    ,gmv_usd as gmv
from
    mp_content_oa.dwd_ls_order_omni_local_content_final_detail_di
where
    grass_region in (${grass_region})
    and grass_date between date_add(date(${local_date}), -14) and date(${local_date})
    and order_cal_type = 'direct'
    and tz_type = 'local'
    and is_content_directly_related = 1
;

--sql_divide_splitter--
create temporary view order_antifraud_tag_${grass_region_without_quote} as
select
    order_id
    ,tag as antifraud_tag -- 0: Brushing, 1: Abuse
from
    szci_antifraud.dws_ob_online_s1_di
where
    grass_region in (${grass_region})
    and grass_date between date_add(date(${local_date}), -14) and date(${local_date})
group by 1, 2
;

--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_content_antifraud_user_item_level_order_metrics_1d
partition(grass_region = ${grass_region}, local_date)

select
    user_id
    ,item_id
    ,scenario
    ,is_ads
    ,coalesce(antifraud_tag, -1) as antifraud_tag

    ,sum(order_cnt) as order_cnt
    ,sum(gmv) as gmv

    ,local_date
from
    user_item_${grass_region_without_quote} as t1
left join
    order_antifraud_tag_${grass_region_without_quote} as t2
on
    t1.order_id = t2.order_id
group by 1, 2, 3, 4, 5, local_date
;
